        "aiRecommendation":  "ลูกค้าระดับ Star Growth (10482913) พันธมิตร VIP ร้านคู่ยงฮวด ช่างเปิดรับทีมเทคนิค SCG เข้าแนะนำปูนเสือ สกิมโค้ทและหลังคา SCG Prestige แนะนำต่อยอด Total Solution ด่วน",
        "customDiagnostic":  "บริษัทรับสร้างบ้านพรีเมียมสไตล์ Modern Classic Luxury (งบ 3-8 ล้านบาท) ที่มียอดสั่งซื้อ SCG ปี 2026 เติบโตก้าวกระโดดสูงถึง \u003cstrong\u003e฿3,396,188 (+116.3% YoY)\u003c/strong\u003e เป็นลูกค้าระดับ VIP ของร้านผู้แทนจำหน่าย SCG \u0027คู่ยงฮวด\u0027 และมีความร่วมมือเปิดรับทีมเทคนิค SCG เข้าสาธิตการใช้งานปูนเสือ สกิมโค้ท และระบบหลังคา SCG Prestige ถึงหน้างานจริง มีงานสร้างบ้านกระจายตัวทั่ว จ.อุดรธานี",
        "customRecommendations":  [
                                      "\u003cstrong\u003eระบบหลังคาคอนกรีต SCG Prestige \u0026 อุปกรณ์ครอบแห้ง Dry-Tech:\u003c/strong\u003e ล็อกสเปกหลังคา SCG Prestige คู่แผ่นสะท้อนความร้อน Ultra Cool และฉนวน STAY COOL เป็นมาตรฐานสำหรับบ้าน Modern Classic ทุกหลัง",
                                      "\u003cstrong\u003eปูนเสือ สกิมโค้ท (Tiger Skim Coat) \u0026 ปูนฉาบละเอียด:\u003c/strong\u003e ต่อยอดความสำเร็จจากไซต์สาธิต อ.กุดจับ สู่การทำสัญญาเหมาปูนเสือ สกิมโค้ทและปูนเสือ มอร์ตาร์ สำหรับทุกไซต์งานใน อ.เมือง, สามพร้าว และหนองใส",
                                      "\u003cstrong\u003eคอนกรีตผสมเสร็จ CPAC 240-280 ksc งานโครงสร้าง:\u003c/strong\u003e นำเสนอคอนกรีต CPAC สำหรับงานหล่อเสาคานและพื้นชั้น 2 พร้อมประสานงานส่งตรงผ่านเครือข่ายคู่ยงฮวด",
                                      "\u003cstrong\u003eชุดสุขภัณฑ์และก๊อกน้ำ COTTO Touchless:\u003c/strong\u003e นำเสนอสุขภัณฑ์ประหยัดน้ำและอุปกรณ์ห้องน้ำ COTTO เกรดพรีเมียม ตอบโจทย์บ้านเดี่ยวระดับ 3 ล้านบาทขึ้นไป"
                                  ],
