        "customDiagnostic":  "บริษัทรับสร้างบ้านเดี่ยวคุณภาพมาตรฐานใน จ.อุดรธานี (นิติพันธ์สร้างบ้านอุดรธานี) มียอดสั่งซื้อ SCG สม่ำเสมอ \u003cstrong\u003e฿569,818\u003c/strong\u003e (+2.89% YoY, SCG Code 10383888) มีการบริหารงานแบบเจ้าของคุมงานใกล้ชิด (คุณนิติพันธ์ และคุณแบงค์) ตรวจพบไซต์งานจริง 2 โครงการ ได้แก่ ไซต์บ้านดอนหาด (งานฉาบและปูกระเบื้อง) และไซต์ใหม่โซนเมืองอุดรฯ (เพิ่งทำพิธียกเสาเอก-เสาโท) มีโอกาสสูงในการขยายยอดซื้อคอนกรีต CPAC, ปูนฉาบเสือมอร์ตาร์ และกระเบื้อง-สุขภัณฑ์ COTTO",
