                             "caption":  "📣 #ประกาศปิดรับงานก่อสร้างชั่วคราว 📣 \n\nเนื่องจากขณะนี้ คิวงานจองยกเสาเต็มยาว\nถึงเดือนธันวาคม 2569 เรียบร้อยแล้ว 🏡✨\nทางบริษัทจึงขอ #ปิดรับเคสใหม่ชั่วคราว \nเพื่อดูแลและบริหารงานของลูกค้าที่อยู่ในคิว\nให้เป็นไปตามแผนและมีคุณภาพมากที่สุด\n\nหากมีคิวช่างว่าง หรือมีคิวหลุดจอง\nทางบริษัทจะแจ้ง เปิดรับเคสเพิ่มเติมอีกครั้ง\nผ่านทางหน้าเพจ\n\n🙏 #กราบขอบพระคุณลูกค้าทุกท่านจากใจ 🙏\nที่ให้ความไว้วางใจและเลือกใช้บริการสร้างบ้านกับ\n🏡🏡 ห้างหุ้นส่วนจำกัดรุ่งรัตน์บิวตี้โฮม 🏡🏡\n\nด้วยดีเสมอมา ทุกความไว้วางใจของลูกค้า \nคือกำลังใจสำคัญที่ทำให้เราตั้งใจพัฒนางาน\nและดูแลบ้านทุกหลังให้ดีที่สุดค่ะ 🤍🏡\n\nแล้วพบกันอีกครั้งเมื่อเปิดรับคิวใหม่ค่ะ \n\n📞 สอบถามข้อมูลเพิ่มเติม ติดต่อได้ที่\nFacebook https://www.facebook.com/share/17si2DzJVW/?mibextid=wwXIfr\nคุณกิ๊ฟ☎️ 098-134-5273\n📱 LINE ID : 2530gip\nคุณอุ้ม☎️ 098-435-0263\n📱 LINE ID : 2530um",
