                               "caption":  "Site Update - งานก่อสร้างบ้านพักอาศัย 1 ชั้น \nของคุณกนกวรรณและครอบครัว\nที่ตั้ง : ซอยสุขคณา อ.เมืองอุดรธานี\n.\n▶️งานเทคอนกรีตฐานราก\n.\n#117อาร์คิเทคท์ รับสร้างบ้านและออกแบบ\n𝙘𝙤𝙣𝙨𝙩𝙧𝙪𝙘𝙩𝙞𝙤𝙣 𝙘𝙤𝙣𝙩𝙧𝙖𝙘𝙩𝙤𝙧 🎊👷\nออกแบบ | ก่อสร้าง | ต่อเติม | ประเมินต้นทุน |\n𝙍𝙚𝙨𝙥𝙤𝙣𝙨𝙞𝙗𝙡𝙚🎊🏠\n👷วัสดุก่อสร้างที่ได้มาตรฐาน\n👷ตรวจประเมินหน้างานก่อนก่อสร้าง ฟรี !!\n👷ให้คำปรึกษาแนะนำด้านการเงิน ยื่นกู้ธนาคาร\n👷ใส่ใจในงาน และมีทีมช่างโดยเฉพาะในเเต่ละงาน\n👷ออกแบบ เขียนแบบโดย สถาปนิก วิศวกร ที่มีใบประกอบวิชาชีพรับรอง\n👷ควบคุมงาน โดยทีมงานคุณภาพที่มีประสบการณ์โดยตรง\n.\n 🔹ไม่ทิ้งงาน\n 🔹บริการหลังการก่อสร้างมีงานรับประกันเรียกใช้ได้ทันที\n 🔹ปรึกษาเรื่องแบบ เรื่องบ้าน เรื่องสินเชื่อ(ฟรี) ไม่มีค่าใช่จ่าย\n 🔹สร้างจบงบไม่บานปลาย\n 🔹ขึ้นงานภาพ 3D ให้มองเห็นภาพเสมือนจริงก่อนงานสร้างแล้วเสร็จ\n✨ งานรับประกัน ✨\n✅ประกันงานโครงสร้าง 15 ปี\n✅ประกันงานหลังคา 5 ปี\n✅ประกันงานวัสดุก่อสร้างทั่วไป 1 ปี\n✅ประกันดูแลงานระบบกำจัดปลวก 3 ปี\n✅งานสกิมโค้ททั้งหลัง\n✅เดินสายเมนไฟร้อยท่อฝังลงดิน  \n  #บ้านในฝันของคุณคือความภูมิใจของเรา   \nติดต่อสอบถามรายละเอียด :\n☎️ Tel : 089 615 9559\n📩 E-mail : 117architect@gmail.com  \n📩 Line : 117architect\n📩 Inbox : https://www.facebook.com/359779854451767/\n🏠 Facebook : https://www.facebook.com/PhongsakRuangsiwakun\nIG : @117architect\nYouTube  : https://www.youtube.com/@117architect7",
