                             "caption":  "🏠 บ้านชั้นเดียว 84 ตร.ม.\n 2 ห้องนอน 2 ห้องน้ำ 1 ห้องนั่งเล่น 1 ห้องครัว\nงบประมาณ 1.2-1.4 ล้าน\n\nจุดเด่นของแปลนนี้\n\n* แยกโซนพักผ่อนกับโซนครัวชัดเจน\n* ห้องนอนใหญ่มีความเป็นส่วนตัว\n* เหมาะกับบ้านขนาดประมาณ 8×12 เมตร\n\nโซนกลางบ้าน\n\n* จากห้องนั่งเล่น เดินเข้าไปจะเป็นโถงเล็ก\n* แยกซ้าย–ขวาเป็น:\n    * ห้องนอนเล็ก (Bedroom 1)\n    * ห้องน้ำกลาง (Bathroom 1) ใช้ร่วม\n\nโซนด้านขวาของบ้าน\n\n* ห้องนอนใหญ่ (Master Bedroom) อยู่มุมเงียบ\n* มี ห้องน้ำในตัว (Bathroom 2)\n\nโซนด้านหลัง\n\n* ต่อจากห้องนั่งเล่น/โถง → เป็น ห้องครัว (Kitchen) อยู่ด้านหลังบ้าน\n* อาจมีประตูออกหลังบ้านสำหรับซักล้าง",
                             "postedTime":  "27/5/2569",
                             "postUrl":  "https://www.facebook.com/permalink.php?story_fbid=pfbid02akmkp1btqPcEeFgMmc7aLijcXA7oYVEQb2dHxNtAeb9fGmBRDBfyEaE68E4iMtUzl\u0026id=100063894943820",
